<script setup lang="ts">
import {Link,router} from '@inertiajs/vue3';import SelectField from './SelectField.vue';import Pagination from './Pagination.vue';import {money,dateLabel} from '../lib/format';
defineProps<{accounts:any[];detail:any}>();const emit=defineEmits<{transaction:[id:string]}>();
function selectAccount(id:string|number|null){router.get('/investments',{account:id});}
</script>
<template><div v-if="detail?.account"><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><label class="flex items-center gap-3">Account<SelectField :model-value="detail.account.id" class="min-w-60" :options="accounts.map(a=>({value:a.id,label:a.name}))" @change="selectAccount"/></label><Link :href="'/accounts/'+detail.account.id" class="btn">Account details</Link></div><div class="mb-6 grid grid-cols-2 gap-4 xl:grid-cols-4"><div v-for="[label,value] in [['Account balance',detail.account.balance_cents],['Holdings value',detail.summary.holdings_cents],['Gain / loss',detail.summary.gain_cents],['Cash',detail.summary.cash_cents]]" :key="label" class="panel p-5"><p class="help">{{label}}</p><p class="money mt-2 text-2xl">{{money(value)}}</p><p v-if="label==='Gain / loss'&&detail.summary.gain_percent!==null" class="help mt-1">{{detail.summary.gain_percent.toFixed(2)}}% of cost basis</p></div></div><p class="help mb-6">{{detail.snapshot?'Holdings observed '+dateLabel(detail.snapshot.observed_at):'Holdings have not been supplied.'}} Missing values, cost basis and cash remain unknown. Cash is shown only when explicitly reported.</p>
<section class="panel mb-6 overflow-x-auto"><h2 class="px-5 py-4 text-base">Holdings</h2><table v-if="detail.positions.data.length"><thead><tr><th>Holding</th><th>Quantity</th><th>Price</th><th>Market value</th><th>Cost basis</th><th>Gain / loss</th></tr></thead><tbody><tr v-for="position in detail.positions.data" :key="position.id"><td><p class="font-medium">{{position.symbol||position.description}}</p><p v-if="position.symbol" class="help">{{position.description}}</p></td><td class="money">{{Number(position.quantity).toLocaleString('en-US',{maximumFractionDigits:10})}}</td><td class="money">{{position.unit_price===null?'Unknown':'$'+Number(position.unit_price).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:8})}}</td><td class="money">{{money(position.market_value_cents)}}</td><td class="money">{{money(position.cost_basis_cents)}}</td><td class="money">{{position.cost_basis_cents===null||position.market_value_cents===null?'Unknown':money(Number(position.market_value_cents)-Number(position.cost_basis_cents))}}</td></tr></tbody></table><p v-else class="empty">The provider has not supplied holdings for this account.</p><Pagination :records="detail.positions"/></section>
<section class="panel overflow-x-auto"><h2 class="px-5 py-4 text-base">Trading & cash activity</h2><p class="help px-5 pb-4">Imported account activity appears here. Classify a transaction as an investment purchase or sale to keep it out of Budget. Security and quantity details are shown only in reported holdings.</p><table><thead><tr><th>Date</th><th>Activity</th><th>Description</th><th>Amount</th><th/></tr></thead><tbody><tr v-for="entry in detail.activity?.data||[]" :key="entry.id"><td>{{dateLabel(entry.activity_date)}}</td><td>{{entry.kind.replaceAll('_',' ')}}</td><td>{{entry.description||'Reported investment activity'}}</td><td class="money" :class="Number(entry.amount_cents)>0?'text-income':''">{{money(entry.amount_cents)}}</td><td><button v-if="entry.transaction_id" class="btn" @click="emit('transaction',entry.transaction_id)">View transaction</button></td></tr></tbody></table><div v-if="!detail.activity?.data.length" class="empty"><p>No investment activity imported yet.</p><Link href="/household" class="btn">Manage bank connection</Link></div><Pagination :records="detail.activity"/></section></div><div v-else class="panel empty"><p>No investment accounts connected.</p><p class="help max-w-md">Connect an investment account to see reported holdings and activity.</p><Link href="/household" class="btn">Bank connections</Link></div></template>
